const assignee = $('Fetch Assignee').first().json;
const body = $('Webhook').first().json.body;
const appUrl = process.env.APP_URL || 'https://app.cmmc4msp.on-nex.us';
const deepLink = `${appUrl}/${assignee.org_slug}/controls/${body.program_control_id}`;

const verdictColors = { met: '#16a34a', partial: '#d97706', not_met: '#dc2626', not_applicable: '#6b7280' };
const verdictLabels = { met: 'Met', partial: 'Partially Met', not_met: 'Not Met', not_applicable: 'Not Applicable' };
const color = verdictColors[body.verdict] || '#6b7280';
const label = verdictLabels[body.verdict] || body.verdict;

const html = `
<!DOCTYPE html>
<html>
<head><meta charset="utf-8"><title>Assessment Complete</title></head>
<body style="font-family: Arial, sans-serif; background: #f9fafb; margin: 0; padding: 20px;">
  <div style="max-width: 560px; margin: 0 auto; background: #fff; border-radius: 8px; border: 1px solid #e5e7eb; overflow: hidden;">
    <div style="background: #1d4ed8; padding: 24px 32px;">
      <h1 style="color: #fff; margin: 0; font-size: 18px;">CMMC Compliance OS</h1>
    </div>
    <div style="padding: 32px;">
      <h2 style="margin: 0 0 16px; color: #111827; font-size: 20px;">Assessment Complete</h2>
      <p style="color: #374151; margin: 0 0 8px;">Control <strong>${assignee.nist_id}</strong> in <strong>${assignee.program_name}</strong> has been assessed.</p>
      <div style="display: inline-block; background: ${color}; color: #fff; padding: 6px 16px; border-radius: 20px; font-size: 14px; font-weight: 600; margin-bottom: 24px;">${label}</div>
      <p style="color: #374151; margin: 0 0 24px; font-size: 13px;">${assignee.requirement_text ? assignee.requirement_text.substring(0, 150) + '...' : ''}</p>
      <a href="${deepLink}" style="display: inline-block; background: #1d4ed8; color: #fff; text-decoration: none; padding: 12px 24px; border-radius: 6px; font-weight: 600;">View Control</a>
    </div>
    <div style="background: #f9fafb; border-top: 1px solid #e5e7eb; padding: 16px 32px;">
      <p style="color: #9ca3af; font-size: 11px; margin: 0;">You received this because you are assigned to this control. <a href="${appUrl}/unsubscribe" style="color: #9ca3af;">Unsubscribe</a></p>
    </div>
  </div>
</body>
</html>`;

return [{
  json: {
    to: assignee.email,
    subject: `Assessment ${label}: ${assignee.nist_id} — ${assignee.program_name}`,
    html,
    user_id: assignee.user_id,
    program_control_id: body.program_control_id,
  }
}];
